const base = {action:'sui-burn',suiOwner:f.suiOwner,evmOwner:cf.owner,amount:100000n,maxCctpFee:100n,gasCeiling:50000000n}
function controlled() {
 let saved=null,now=Date.now(),current=true,gate=true,signs=0,sends=0,checks=0,locked=false
 const p={prepare:async()=>({bytes:new Uint8Array([1,2]),digest:'controlled-digest',estimatedGas:1n,maximumGas:2n,binding:'controlled',expiresAt:now+100000}),recheck:async()=>{checks++},sign:async(_i,bytes)=>{signs++;return{bytes,signature:'controlled'}},validateSigned:async()=> 'controlled-digest',broadcast:async()=>{sends++},recover:async()=> 'verified'}
 const e={gate:()=>gate,current:()=>current,now:()=>now,load:()=>saved,save:a=>{saved=structuredClone(a)},lock:async(_owner,fn)=>{if(locked)throw Error('locked');locked=true;try{return await fn()}finally{locked=false}}}
 const api=c.createSuiWriteController(p,e)
 return {api,p,e,get saved(){return saved},get signs(){return signs},get sends(){return sends},get checks(){return checks},set current(x){current=x},set gate(x){gate=x},advance:ms=>{now+=ms}}
}
await test('write gates stay open and there is no product cap: 0.1, 0.100001, 1, 10 and 100 USDC reach Review; a closed gate still blocks Confirm',async()=>{assert.equal(cfg.MAINNET_SUI_CCTP_WRITES_ENABLED,true);assert.equal(cfg.MAINNET_ARC_WALLET_SEND_ENABLED,true);assert.equal('MAINNET_SUI_CCTP_TEST_MAX_UNITS' in cfg,false);assert.equal('assertSuiTestAmount' in c,false);assert.equal(c.browserSuiWriteEnvironment(()=>true).gate(),true);for(const amount of [100000n,100001n,1000000n,10000000n,100000000n]){const y=controlled(),r=await y.api.prepare({...base,amount});assert.equal(r.intent.amount,amount);assert.equal(y.signs+y.sends,0)}const x=controlled(),review=await x.api.prepare({...base,amount:100000000n});x.gate=false;await assert.rejects(()=>x.api.confirm(review),/disabled/);assert.equal(x.signs,0)})
await test('prepare is read-only; explicit confirm rechecks twice and broadcasts once with durable digest',async()=>{const x=controlled(),review=await x.api.prepare(base);assert.equal(x.signs,0);assert.equal(x.sends,0);x.p.broadcast=async()=>{assert.equal(x.saved.state,'broadcasting');assert.equal(x.saved.digest,'controlled-digest')};await x.api.confirm(review);assert.equal(x.checks,2);assert.equal(x.saved.state,'pending');await assert.rejects(()=>x.api.confirm(review));assert.equal(x.signs,1)})
await test('caller-cloned review cannot supply different economic authority',async()=>{const x=controlled(),review=await x.api.prepare(base);await assert.rejects(()=>x.api.confirm({...review,intent:{...base,amount:200000n}}));assert.equal(x.signs,0)})
await test('bad amounts, fees, owners and missing mint source fail before prepare',async()=>{for(const a of [{amount:0n},{amount:1n<<64n},{maxCctpFee:100000n},{gasCeiling:0n},{suiOwner:'0x0'},{action:'sui-mint'}]){const x=controlled();await assert.rejects(()=>x.api.prepare({...base,...a}));assert.equal(x.signs,0)}})
await test('gas drift and failed simulation cannot authorize a review',async()=>{for(const mutate of [x=>x.p.prepare=async()=>({bytes:new Uint8Array([1]),binding:'x',expiresAt:Date.now()+1000,estimatedGas:3n,maximumGas:2n}),x=>x.p.prepare=async()=>{throw Error('simulation failed')}]){const x=controlled();mutate(x);await assert.rejects(()=>x.api.prepare(base));assert.equal(x.signs,0)}})
await test('expired review and changed account/chain/input fail before signing',async()=>{for(const mutate of [x=>x.advance(100001),x=>x.current=false,x=>x.api.invalidate()]){const x=controlled(),review=await x.api.prepare(base);mutate(x);await assert.rejects(()=>x.api.confirm(review));assert.equal(x.signs,0)}})
await test('wallet delay beyond review expiry never broadcasts the late signature',async()=>{const x=controlled(),review=await x.api.prepare(base);x.p.sign=async(_i,bytes)=>{x.advance(100001);return{bytes,signature:'late'}};await assert.rejects(()=>x.api.confirm(review),/needs checking/);assert.equal(x.sends,0);assert.equal(x.saved.state,'unknown')})
await test('wallet/account change during signature invalidates the signed transaction',async()=>{const x=controlled(),review=await x.api.prepare(base);x.p.sign=async(_i,bytes)=>{x.current=false;return{bytes,signature:'controlled'}};await assert.rejects(()=>x.api.confirm(review));assert.equal(x.sends,0)})
await test('post-sign simulation/nonce/balance failure retains recovery record and cannot send',async()=>{const x=controlled(),review=await x.api.prepare(base);let n=0;x.p.recheck=async()=>{if(++n===2)throw Error('nonce changed')};await assert.rejects(()=>x.api.confirm(review));assert.equal(x.sends,0);assert.equal(x.saved.state,'unknown');await assert.rejects(()=>x.api.prepare(base),/unresolved/)})
await test('storage failure precedes signature; double-click and second controller are excluded',async()=>{const x=controlled(),review=await x.api.prepare(base);x.e.save=()=>{throw Error('storage unavailable')};await assert.rejects(()=>x.api.confirm(review));assert.equal(x.signs,0);const y=controlled(),a=await y.api.prepare(base);let release;y.p.sign=(_i,bytes)=>new Promise(resolve=>{release=()=>resolve({bytes,signature:'controlled'})});const first=y.api.confirm(a);while(!release)await new Promise(resolve=>setTimeout(resolve,0));await assert.rejects(()=>y.api.confirm(a));const second=c.createSuiWriteController(y.p,y.e);await assert.rejects(()=>second.prepare(base),/unresolved/);release();await first;assert.equal(y.sends,1)})
await test('broadcast timeout/error preserves known ID; reload cannot resubmit and recovery never sends',async()=>{const x=controlled(),review=await x.api.prepare(base);x.p.broadcast=async()=>{throw Error('response lost after submission')};await assert.rejects(()=>x.api.confirm(review));assert.equal(x.saved.digest,'controlled-digest');const reloaded=c.createSuiWriteController(x.p,x.e);await assert.rejects(()=>reloaded.prepare(base));assert.equal((await reloaded.recover()).state,'verified');assert.equal(x.signs,1);assert.equal(x.sends,0)})
await test('pending and RPC error recovery never release unresolved attempt',async()=>{const x=controlled(),review=await x.api.prepare(base);await x.api.confirm(review);x.p.recover=async()=> 'pending';assert.equal((await x.api.recover()).state,'pending');x.p.recover=async()=>{throw Error('RPC unavailable')};await assert.rejects(()=>x.api.recover());assert.equal(x.saved.state,'pending');await assert.rejects(()=>x.api.prepare(base))})
await test('wallet change during recovery cannot publish a stale active success',async()=>{const x=controlled(),review=await x.api.prepare(base);await x.api.confirm(review);x.p.recover=async()=>{x.current=false;return 'verified'};await assert.rejects(()=>x.api.recover(),/changed during recovery/);assert.equal(x.saved.state,'pending')})
await test('explicit sign-only rejection/unsupported method causes no broadcast and no hidden fallback',async()=>{for(const reason of ['user','unsupported']){const x=controlled(),review=await x.api.prepare(base);x.p.sign=async()=>{throw new c.SuiWriteSignatureRejected(reason)};await assert.rejects(()=>x.api.confirm(review),c.SuiWriteSignatureRejected);assert.equal(x.saved.state,'rejected');assert.equal(x.sends,0)}})
await test('bounded preparation timeout cannot publish a late review or request a signature',async()=>{const x=controlled();let release;const original=x.p.prepare;x.p.prepare=()=>new Promise(resolve=>{release=resolve});const timer=globalThis.setTimeout;globalThis.setTimeout=(fn,ms,...a)=>timer(fn,ms===45000?2:ms,...a);try{await assert.rejects(()=>x.api.prepare(base),/timed out/);release(await original());await Promise.resolve();assert.equal(x.signs,0);assert.equal(x.saved,null)}finally{globalThis.setTimeout=timer}})
await test('wallet timeout aborts the sign-only request; a late response is never broadcast',async()=>{const x=controlled(),review=await x.api.prepare(base);let release,signal;x.p.sign=(_i,bytes,s)=>{signal=s;return new Promise(resolve=>{release=()=>resolve({bytes,signature:'late'})})};const timer=globalThis.setTimeout;globalThis.setTimeout=(fn,ms,...a)=>timer(fn,ms===90000?2:ms,...a);try{await assert.rejects(()=>x.api.confirm(review),/needs checking/);assert.equal(signal.aborted,true);release();await Promise.resolve();assert.equal(x.sends,0);assert.equal(x.saved.state,'unknown')}finally{globalThis.setTimeout=timer}})
await test('real Web Locks boundary fails closed when unavailable and journal stores no signed bytes',async()=>{const old=globalThis.navigator;Object.defineProperty(globalThis,'navigator',{value:{},configurable:true});try{const env=c.browserSuiWriteEnvironment(()=>true);await assert.rejects(()=>env.lock('owner',async()=>{}),/cannot safely/);env.save({id:'test',intent:base,commitment:v.keccak256(new Uint8Array([1])),createdAt:Date.now(),state:'pending',digest:f.sourceDigest,signature:'MUST NOT STORE',bytes:'MUST NOT STORE'});const raw=local.get('machina_mainnet_sui_write_attempt_v1');assert.doesNotMatch(raw,/MUST NOT STORE|signature|bytes/);assert.equal(env.load().intent.amount,100000n);local.set('machina_mainnet_sui_write_attempt_v1','{bad');assert.throws(()=>env.load(),/unreadable/);local.clear()}finally{Object.defineProperty(globalThis,'navigator',{value:old,configurable:true})}})

