// ---- Arc eth_sendTransaction (wallet-send) controlled EIP-1193 wallet -------------------------------
// The fake wallet is the ONLY place eth_sendTransaction exists. It signs with a local test key and
// "broadcasts" into the controlled Arc RPC map. No live wallet, RPC or Mainnet broadcast is involved.
function wsFixture(action='arc-burn',mode='honest',deps={allowWalletSend:true}){
 const x=sdkFixture(action,deps);x.i={...x.i,arcMethod:'wallet-send'};x.sent=[];x.count.walletSend=0;const original=x.provider.request
 x.release=null
 x.provider.request=async a=>{
  if(a.method!=='eth_sendTransaction')return original(a)
  x.count.walletSend++;const p=a.params[0];x.sent.push(p)
  if(mode==='reject')throw{code:4001};if(mode==='unsupported')throw{code:4200};if(mode==='disconnect')throw new Error('socket closed');if(mode==='nohash')return null
  if(mode==='hang')return new Promise(()=>{})
  const t={type:'eip1559',chainId:5042,to:p.to,data:p.data,value:BigInt(p.value),nonce:Number(BigInt(p.nonce)),gas:BigInt(p.gas),maxFeePerGas:BigInt(p.maxFeePerGas),maxPriorityFeePerGas:BigInt(p.maxPriorityFeePerGas),accessList:[]}
  if(mode==='nonce')t.nonce++;if(mode==='data')t.data='0x1234';if(mode==='to')t.to=cf.other;if(mode==='fee')t.maxFeePerGas*=2n;if(mode==='lowfee')t.maxFeePerGas-=1n;if(mode==='gas')t.gas+=1n;if(mode==='value')t.value=1n;if(mode==='access')t.accessList=[{address:cf.other,storageKeys:[]}]
  const raw=await ek.signTransaction(t)
  if(mode==='otherchain')return v.keccak256(raw) // broadcast somewhere that is not Arc
  const hash=await x.evm.sendRawTransaction({serializedTransaction:raw})
  if(mode==='late')return new Promise(resolve=>{x.release=()=>resolve(hash)})
  return hash
 }
 return x
}
function journal(x){let saved=null,fail=false;const states=[];return{env:{gate:()=>true,current:()=>x.holder.current,now:()=>Date.now(),lock:async(_,fn)=>fn(),load:()=>saved,save:a=>{if(fail)throw Error('journal write failed');states.push([a.state,x.count.walletSend,a.expected?{...a.expected}:undefined]);saved=structuredClone(a)}},states,fail:()=>{fail=true},get:()=>saved}}
const queued=d=>(local.get('machina_mainnet_sui_transfers_v1')??'').includes(d)
for(const action of ['arc-approval','arc-burn','arc-mint'])await test(`wallet-send ${action}: no wallet request before Confirm, durable intent BEFORE the single eth_sendTransaction, independent RPC field check, verified`,async()=>{local.clear();const x=wsFixture(action),j=journal(x),api=c.createSuiWriteController(x.port,j.env),review=await api.prepare(x.i)
 assert.equal(x.count.walletSend+x.count.evmSign+x.count.evmSend,0);assert.match(review.content.join('\n'),action==='arc-approval'?/approve: .*exactly 0\.1 USDC/:action==='arc-burn'?/depositForBurn: 0\.1 USDC to domain 8/:/receiveMessage/)
 const a=await api.confirm(review);assert.equal(a.state,'pending');assert.equal(x.count.walletSend,1);assert.equal(x.count.evmSign,0)
 assert.deepEqual(j.states[0].slice(0,2),['sending',0]);const e=j.states[0][2],sent=x.sent[0];assert.ok(e&&e.nonce===Number(BigInt(sent.nonce))&&e.to.toLowerCase()===sent.to.toLowerCase()&&e.dataHash===v.keccak256(sent.data)&&e.gas===BigInt(sent.gas)&&e.maxFeePerGas===BigInt(sent.maxFeePerGas))
 assert.equal(sent.chainId,'0x13b2');assert.equal(sent.from,evmOwner);assert.equal(sent.value,'0x0');if(action==='arc-mint')assert.match(e.cctpNonce,/^0x[0-9a-f]{64}$/)
 assert.equal((await api.recover()).state,'verified');await assert.rejects(()=>api.confirm(review));assert.equal(x.count.walletSend,1);assert.equal(queued(a.digest),action==='arc-burn')})
