// Chain model for lost-hash tests: the sender's nonce becomes nonce+1 at block B (historical state).
function chainAt(x,e,B,txs,{history=true,anyBlock=false}={}){x.evm.getTransactionCount=async({blockNumber,blockTag})=>{if(blockTag)return x.holder.nonce;if(!history)throw Error('missing trie node');return blockNumber>=B?e.nonce+1:e.nonce};x.evm.getBlock=async({blockNumber,includeTransactions}={})=>({number:blockNumber??B+5n,hash:cf.bh,baseFeePerGas:1n,transactions:includeTransactions&&(anyBlock||blockNumber===B)?txs:[]})}
async function lostSend(action){const x=wsFixture(action,'disconnect',{allowWalletSend:true,paceMs:0}),j=journal(x),api=c.createSuiWriteController(x.port,j.env),r=await api.prepare(x.i);await assert.rejects(()=>api.confirm(r));const e=j.get().expected,raw=await ek.signTransaction({type:'eip1559',chainId:5042,to:e.to,data:x.sent[0].data,value:0n,nonce:e.nonce,gas:e.gas,maxFeePerGas:e.maxFeePerGas,maxPriorityFeePerGas:BigInt(x.sent[0].maxPriorityFeePerGas),accessList:[]}),hash=await x.evm.sendRawTransaction({serializedTransaction:raw});x.holder.nonce=e.nonce+1;return{x,j,api,e,hash}}
await test('lost hash recovery: nonce binary search finds the exact (sender, nonce) transaction; recover then checks fields, receipt and CCTP/approval events -> verified',async()=>{for(const action of ['arc-approval','arc-burn','arc-mint']){const {x,j,api,e,hash}=await lostSend(action),B=e.fromBlock+37n;chainAt(x,e,B,[{hash,from:evmOwner,nonce:e.nonce},{hash:'0x'+'e'.repeat(64),from:cf.other,nonce:e.nonce}]);let logs=0;x.evm.getLogs=async()=>{logs++;return[]};const out=await api.recover();assert.equal(out.state,'verified');assert.equal(out.digest,hash);assert.equal(logs,0);assert.equal(j.get().state,'verified');assert.equal(x.count.walletSend,1)}})
await test('lost hash recovery fallback (no historical state): bounded event search near the review, exact (sender, nonce) match only',async()=>{for(const action of ['arc-approval','arc-burn','arc-mint']){const {x,api,e,hash}=await lostSend(action);chainAt(x,e,e.fromBlock+3n,[],{history:false});const seen=[];x.evm.getLogs=async q=>{seen.push(q);return[{transactionHash:hash}]};const out=await api.recover();assert.equal(out.state,'verified');assert.equal(out.digest,hash);assert.ok(seen.length>=1&&seen.length<=2&&seen[0].fromBlock===e.fromBlock);assert.equal(seen[0].event.name,action==='arc-approval'?'Approval':action==='arc-burn'?'DepositForBurn':'MessageReceived');if(action==='arc-mint')assert.equal(seen[0].args.nonce,e.cctpNonce)}})
