 let {x,j,api,e}=await lostSend('arc-burn');chainAt(x,e,e.fromBlock-10n,[]);await assert.rejects(()=>api.recover(),/stays blocked/);assert.equal(j.get().state,'unknown')
 ;({x,j,api,e}=await lostSend('arc-burn'));const B=e.fromBlock+2n;chainAt(x,e,B,[{hash:'0x'+'c'.repeat(64),from:evmOwner,nonce:e.nonce},{hash:'0x'+'d'.repeat(64),from:evmOwner,nonce:e.nonce}]);await assert.rejects(()=>api.recover(),/stays blocked/)
