// A recorded mismatch on a settled, canonical chain (head well past the receipt, sender nonce consumed, nothing pending).
async function mismatched(mode='fee',action='arc-burn'){local.clear();const x=wsFixture(action,mode,{allowWalletSend:true,paceMs:0}),j=journal(x),api=c.createSuiWriteController(x.port,j.env),r=await api.prepare(x.i),a=await api.confirm(r);assert.equal((await api.recover()).state,'mismatch');x.holder.nonce=j.get().expected.nonce+1;x.evm.getBlock=async({blockNumber}={})=>({number:blockNumber??200n,hash:cf.bh,baseFeePerGas:1n});const receipt=x.arcReceipts.get(a.digest);return{x,j,api,a,receipt}}
await test('a mismatch is never re-judged: recover returns the recorded mismatch without consulting the chain again',async()=>{const {x,api}=await mismatched();let calls=0;const g=x.evm.getTransaction;x.evm.getTransaction=async q=>{calls++;return g(q)};assert.equal((await api.recover()).state,'mismatch');assert.equal(calls,0)})
await test('reconciliation step 1 only reads evidence: lines bind sender, nonce, block and every decoded effect; the journal stays locked',async()=>{const {x,j,api,a}=await mismatched(),sends=[x.count.walletSend,x.count.evmSend],ev=await api.reconcile();assert.match(ev.key,/^0x[0-9a-f]{64}$/);assert.equal(ev.digest,a.digest);const t=ev.lines.join('\n');for(const re of [/reviewed nonce \d+ consumed by this transaction; no pending sender transactions/,/in block 100 \(0x/,/CCTP burn 0\.1 USDC .* to domain 8/,/CCTP message sent/,/TokenMessenger allowance after this block/])assert.match(t,re);assert.ok(Object.isFrozen(ev.lines));assert.equal(j.get().state,'mismatch');await assert.rejects(()=>api.prepare({...x.i}),/unresolved/);assert.deepEqual([x.count.walletSend,x.count.evmSend],sends)})
await test('reconciliation step 2 releases only with the acknowledged key and identical fresh evidence; result is reconciled, never verified; no transaction is sent',async()=>{const {x,j,api}=await mismatched(),sends=[x.count.walletSend,x.count.evmSend,x.count.evmSign],ev=await api.reconcile();await assert.rejects(()=>api.reconcile('0x'+'0'.repeat(64)),/changed since it was shown/);assert.equal(j.get().state,'mismatch');const out=await api.reconcile(ev.key);assert.equal(out.state,'reconciled');assert.equal(j.get().state,'reconciled');assert.deepEqual([x.count.walletSend,x.count.evmSend,x.count.evmSign],sends);assert.equal(queued(out.digest),false);await api.prepare({...x.i});await assert.rejects(()=>api.reconcile(ev.key),/Only a recorded wallet-send mismatch/)})
await test('chain evidence changing between display and acknowledgement (reorg/new effect) keeps the lock',async()=>{const {x,j,api,receipt}=await mismatched(),ev=await api.reconcile(),rc=x.evm.readContract;x.evm.readContract=async q=>q.functionName==='allowance'?123n:rc(q);await assert.rejects(()=>api.reconcile(ev.key),/changed since it was shown/);assert.equal(j.get().state,'mismatch');x.evm.readContract=rc;receipt.logs.push({...receipt.logs[0]});await assert.rejects(()=>api.reconcile(ev.key),/stays locked/);assert.equal(j.get().state,'mismatch');receipt.logs.pop();const ev2=await api.reconcile();x.evm.getBlock=async({blockNumber}={})=>({number:blockNumber??200n,hash:'0x'+'bb'.repeat(32)});await assert.rejects(()=>api.reconcile(ev2.key),/not in the canonical chain/);assert.equal(j.get().state,'mismatch')})
