// Re-record the mismatch as a different signed transaction (fields, receipt) on the same settled chain.
async function rewrite(f,{to,data,value=0n,logs,status='success'}){const t=f.x.arcTransactions.get(f.a.digest);const raw=await ek.signTransaction({type:'eip1559',chainId:5042,to:to??t.to,data:data??t.input,value,nonce:t.nonce,gas:t.gas,maxFeePerGas:t.maxFeePerGas,maxPriorityFeePerGas:t.maxPriorityFeePerGas,accessList:[]}),hash=v.keccak256(raw),p=v.parseTransaction(raw);f.x.arcTransactions.set(hash,{...p,value,input:data??t.input,hash,from:evmOwner,blockNumber:100n,blockHash:cf.bh});f.x.arcReceipts.set(hash,{...f.receipt,status,transactionHash:hash,logs:(logs??f.receipt.logs).map(l=>({...l,transactionHash:hash}))});f.j.env.save({...f.j.get(),digest:hash});f.receipt=f.x.arcReceipts.get(hash);return f}
