await test('wallet-send negative: RPC temporarily unavailable keeps the attempt pending; on-chain revert is reverted, not success',async()=>{const x=wsFixture('arc-burn'),j=journal(x),api=c.createSuiWriteController(x.port,j.env),r=await api.prepare(x.i),a=await api.confirm(r),g=x.evm.getTransaction;x.evm.getTransaction=async()=>{throw Error('503')};await assert.rejects(()=>api.recover());assert.equal(j.get().state,'pending');x.evm.getTransaction=g;x.arcReceipts.get(a.digest).status='reverted';assert.equal((await api.recover()).state,'reverted');assert.equal(queued(a.digest),false);assert.equal(x.count.walletSend,1)})
