await test('wallet-send journal survives a browser-format round trip with expected fields; malformed expected is unreadable (fail closed)',async()=>{local.clear();const x=wsFixture('arc-burn'),env={...c.browserSuiWriteEnvironment(()=>true),lock:async(_,fn)=>fn(),gate:()=>true},api=c.createSuiWriteController(x.port,env),r=await api.prepare(x.i);await api.confirm(r);const back=env.load();assert.equal(back.intent.arcMethod,'wallet-send');assert.equal(typeof back.expected.gas,'bigint');assert.equal(back.state,'pending');const raw=JSON.parse(local.get('machina_mainnet_sui_write_attempt_v1'));assert.ok(!/signature|attestation/i.test(JSON.stringify(raw)));raw.expected.dataHash='0x12';local.set('machina_mainnet_sui_write_attempt_v1',JSON.stringify(raw));assert.throws(()=>env.load(),/unreadable/)})
await test('without a product cap the real limits still stop a transfer before any wallet request: CCTP burn limit per message, USDC balance, native gas, u64 range',async()=>{
 for(const action of ['arc-burn','arc-approval']){
  const big=sdkFixture(action);big.i={...big.i,amount:100000000n};if(action==='arc-burn')big.holder.allowance=big.i.amount;big.holder.usdc=100000000n;big.holder.native=101n*10n**18n;const p=await prepare(big);assert.ok(p.bytes.length,'100 USDC prepares when balances cover it')
  const limit=sdkFixture(action);limit.holder.burnLimit=limit.i.amount-1n;await assert.rejects(()=>prepare(limit),/above the CCTP limit of 0\.099999 USDC per transfer on Arc/)
  const unread=sdkFixture(action);unread.holder.minter='0x'+'0'.repeat(40);await assert.rejects(()=>prepare(unread),/CCTP burn limit on Arc could not be read/)
  const poor=sdkFixture(action);poor.i={...poor.i,amount:100000000n};if(action==='arc-burn')poor.holder.allowance=poor.i.amount;poor.holder.usdc=99999999n;poor.holder.native=101n*10n**18n;await assert.rejects(()=>prepare(poor),/balance is insufficient/)
  const gasless=sdkFixture(action);gasless.i={...gasless.i,amount:100000000n};if(action==='arc-burn')gasless.holder.allowance=gasless.i.amount;gasless.holder.usdc=100000000n;gasless.holder.native=100n*10n**18n;await assert.rejects(()=>prepare(gasless),/cannot cover both the token amount and maximum gas/)
  for(const y of [limit,unread,poor,gasless])assert.equal(y.count.sign+y.count.evmSign+y.count.send+y.count.evmSend,0)}
 const sui=sdkFixture('sui-burn');sui.i={...sui.i,amount:100000000n};await prepare(sui)
 const suiPoor=sdkFixture('sui-burn');suiPoor.i={...suiPoor.i,amount:1000000001n};await assert.rejects(()=>prepare(suiPoor),/Sui USDC balance is insufficient|Insufficient balance of 0x[0-9a-f]+::usdc::USDC/);assert.equal(suiPoor.count.sign,0)
 const k=controlled();for(const amount of [0n,-1n,1n<<64n])await assert.rejects(()=>k.api.prepare({...base,amount}),/Invalid Sui\/Arc transfer/);await assert.rejects(()=>k.api.prepare({...base,amount:100n,maxCctpFee:100n}),/Invalid Sui\/Arc transfer/);assert.equal(k.signs,0)
 const a=sdkFixture('arc-approval');a.i={...a.i,amount:123456789n};a.holder.usdc=123456789n;a.holder.native=200n*10n**18n;const q=await prepare(a),tx=v.parseTransaction(v.toHex(q.bytes)),d=v.decodeFunctionData({abi:cf.cfg.CCTP_V2_ERC20_ABI,data:tx.data});assert.equal(d.functionName,'approve');assert.equal(d.args[1],123456789n,'approval covers exactly the transfer amount, never unlimited')})
console.log(`RESULT ${passed}/${passed} Sui/Arc controlled write groups PASS; live RPC, real wallet signatures and Mainnet broadcasts=0. Production gates open; no product cap; CCTP burn limit, balances and gas enforced before any wallet request.`)
